import{_ as n,c as i,o as t,ah as r}from"./chunks/framework.dGCgOE9J.js";const u=JSON.parse('{"title":"26. Netzdaten in QGIS bearbeiten","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.md","filePath":"manual/teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.md"}'),a={name:"manual/teil-b-betrieb-admin-qgis/26-netzdaten-in-qgis-bearbeiten.md"};function d(s,e,l,o,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_26-netzdaten-in-qgis-bearbeiten" tabindex="-1">26. Netzdaten in QGIS bearbeiten <a class="header-anchor" href="#_26-netzdaten-in-qgis-bearbeiten" aria-label="Permalink to &quot;26. Netzdaten in QGIS bearbeiten&quot;">​</a></h1><p>In QGIS bearbeiten Sie die Geometrie des Netzes und die Angaben, die die Weboberfläche nicht anbietet. Die Verbindung zur Datenbank richten Sie ein wie in Kapitel <a href="./25-qgis-arbeitsplatz-einrichten.html">QGIS-Arbeitsplatz einrichten</a> beschrieben. Dieses Kapitel beschreibt, was Qonnectra beim Bearbeiten in QGIS selbst erledigt, was es ablehnt und was danach fehlt. Wie Objekte in QGIS gezeichnet, verschoben und gelöscht werden, beschreibt die QGIS-Dokumentation im Kapitel <a href="https://docs.qgis.org/latest/de/docs/user_manual/working_with_vector/editing_geometry_attributes.html" target="_blank" rel="noreferrer">Bearbeiten</a>.</p><h2 id="_26-1-welche-layer-bearbeitet-werden-durfen" tabindex="-1">26.1 Welche Layer bearbeitet werden dürfen <a class="header-anchor" href="#_26-1-welche-layer-bearbeitet-werden-durfen" aria-label="Permalink to &quot;26.1 Welche Layer bearbeitet werden dürfen&quot;">​</a></h2><p>In QGIS bearbeitet werden die vier Netz-Layer:</p><ul><li><strong>Trassen</strong> (<code>trench</code>) – zeichnen, Verlauf korrigieren, löschen. Die Rohre einer neuen Trasse ordnen Sie anschließend in der Weboberfläche zu, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/11-rohrzuordnung.html">Rohrzuordnung</a>.</li><li><strong>Netzknoten</strong> (<code>node</code>) – setzen, verschieben, löschen. Die Spalte <code>uuid_address</code> verknüpft einen Netzknoten mit einer Adresse; leeren Sie sie, um die Verknüpfung zu lösen, die sich in der Weboberfläche nicht lösen lässt.</li><li><strong>Adressen</strong> (<code>address</code>) – erfassen und verschieben. Die Wohneinheiten einer Adresse legen Sie in der Weboberfläche an, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/16-adressen.html">Adressen</a>.</li><li><strong>Gebiete</strong> (<code>area</code>) – zeichnen und zuschneiden.</li></ul><p>Alles andere bearbeiten Sie in der Weboberfläche oder im Administrationsbereich, auch wenn QGIS die Tabellen öffnen kann: Rohre, Mikrorohre, Kabel, Fasern, Spleiße und der Aufbau der Netzknoten hängen über Verknüpfungen zusammen, die nur die Weboberfläche vollständig pflegt.</p><h2 id="_26-2-pflichtfelder-wertelisten-und-validierung" tabindex="-1">26.2 Pflichtfelder, Wertelisten und Validierung <a class="header-anchor" href="#_26-2-pflichtfelder-wertelisten-und-validierung" aria-label="Permalink to &quot;26.2 Pflichtfelder, Wertelisten und Validierung&quot;">​</a></h2><p>Füllen Sie bei jedem neuen Objekt die Spalten <code>project</code> und <code>flag</code> mit der Nummer des Projekts und des Kennzeichens, dazu die Pflichtspalten des Layers:</p><ul><li>Trassen: <code>construction_type</code> und <code>surface</code></li><li>Netzknoten: <code>name</code> und <code>node_type</code></li><li>Adressen: <code>street</code>, <code>housenumber</code>, <code>zip_code</code> und <code>city</code></li><li>Gebiete: <code>name</code> und <code>area_type</code></li></ul><p>Fehlt eine davon, weist die Datenbank das Objekt beim Speichern ab. Der Name eines Netzknotens und der eines Gebiets darf je Projekt nur einmal vorkommen.</p><p>Einige Spalten füllt die Datenbank selbst. Lassen Sie sie beim Erfassen leer:</p><ul><li><code>uuid</code> – die Kennung jedes Objekts.</li><li><code>id_trench</code> einer neuen Trasse – die Trassen-ID im Format <code>TR-</code> und sieben Zeichen. Eine Trassen-ID in einem anderen Format ersetzt die Datenbank durch eine neue.</li><li><code>length</code> einer Trasse – die Länge aus der Geometrie, bei jeder Änderung neu berechnet.</li><li><code>id_address</code> einer neuen Adresse – die Adress-ID.</li><li><code>geom_3857</code> aller vier Layer – eine Kopie der Geometrie für die Karte der Weboberfläche.</li></ul><p>Stammdaten wie Status, Netzknotentyp oder Oberfläche stehen als Nummern in den Spalten. Erfassen Sie sie über eine Wertbeziehung, siehe Abschnitt <a href="./25-qgis-arbeitsplatz-einrichten.html#_25-3-layer-koordinatenbezugssystem-und-stile">Layer, Koordinatenbezugssystem und Stile</a>; eine Nummer, die es nicht gibt, weist die Datenbank beim Speichern ab.</p><p>Diese Änderungen lehnt die Datenbank ab; QGIS meldet beim Speichern einen Fehler mit dem Grund:</p><table tabindex="0"><thead><tr><th>Änderung</th><th>Meldung (Auszug)</th></tr></thead><tbody><tr><td>Trasse, die sich selbst schneidet oder ungültig ist</td><td>„Geometry is not simple (self-intersecting)“ bzw. „Invalid geometry“</td></tr><tr><td>Netzknoten löschen, an dem Kabel beginnen oder enden</td><td>„Cannot delete node: node has connected cables.“</td></tr><tr><td>Netzknoten löschen, dessen untergeordnete Netzknoten Kabel haben</td><td>„Cannot delete node: child nodes have connected cables.“</td></tr><tr><td>Netzknotentyp ändern, wenn der Netzknoten untergeordnete Netzknoten und Kabel hat</td><td>„Cannot change node type: node has both child nodes and connected cables.“</td></tr><tr><td>übergeordneten Netzknoten ändern, wenn Kabel angeschlossen sind</td><td>„Cannot change parent node: this node has connected cables.“</td></tr></tbody></table><p>Gebiete müssen ebenfalls gültige Flächen sein, ohne Selbstüberschneidung.</p><h2 id="_26-3-gleichzeitiges-arbeiten-mit-der-weboberflache" tabindex="-1">26.3 Gleichzeitiges Arbeiten mit der Weboberfläche <a class="header-anchor" href="#_26-3-gleichzeitiges-arbeiten-mit-der-weboberflache" aria-label="Permalink to &quot;26.3 Gleichzeitiges Arbeiten mit der Weboberfläche&quot;">​</a></h2><p>QGIS und die Weboberfläche arbeiten auf derselben Datenbank. Was Sie in QGIS speichern, gilt sofort; die Karte der Weboberfläche zeigt es nach spätestens 30 Sekunden, das Dashboard nach spätestens fünf Minuten. Ein Objekt in einem Kartenbereich, in dem bis dahin kein Objekt desselben Layers lag, erscheint erst nach bis zu zehn Minuten.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Beim Verschieben prüft die Datenbank einen Abstand von fünf Metern und löscht Mikrorohrverbindungen ohne Meldung:</p><ul><li>Liegt nach dem Verschieben einer Trasse keiner der Netzknoten, an denen ihre Mikrorohre verbunden sind, näher als fünf Meter an irgendeinem Punkt der Trasse, löscht sie alle Mikrorohrverbindungen dieser Trasse – an allen Netzknoten.</li><li>Liegt nach dem Verschieben eines Netzknotens keine Trasse mit Mikrorohrverbindungen näher als fünf Meter, löscht sie alle Mikrorohrverbindungen an diesem Netzknoten.</li></ul><p>Die Rohrverzweigung dort ist danach leer und muss neu verbunden werden, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/12-rohrverzweigung.html">Rohrverzweigung</a>. Bleibt dagegen einer der Netzknoten in der Nähe, bleiben alle Verbindungen bestehen – auch an einem Netzknoten, von dem das Trassenende weggezogen wurde. Prüfen Sie nach dem Verschieben die Rohrverzweigung an den betroffenen Netzknoten.</p></div><p>Was die Weboberfläche bei einer Änderung nebenbei erledigt, geschieht in QGIS nicht:</p><ul><li>Der Ordner der Anhänge wird bei einem Umbenennen nicht verschoben, siehe Abschnitt <a href="./23-dateien-und-anhaenge.html#_23-1-ablagestruktur-der-anhange">Ablagestruktur der Anhänge</a>.</li><li>Der Änderungsverlauf im Administrationsbereich erfährt nichts von der Änderung, siehe Abschnitt <a href="./20-administrationsbereich.html#_20-3-anderungsverlauf-eines-objekts-einsehen">Änderungsverlauf eines Objekts einsehen</a>.</li></ul><p>Ein Rohr, das über die Tabelle in der Datenbank entsteht, bekommt keine Mikrorohre, ein Kabel keine Fasern. Was danach nachzuziehen ist, bieten die Aktionen in Abschnitt <a href="./20-administrationsbereich.html#_20-2-suchen-filtern-und-massenbearbeitung">Suchen, Filtern und Massenbearbeitung</a>. Ein gelöschtes Objekt lässt wie in der Weboberfläche seine Anhänge zurück, siehe Abschnitt <a href="./23-dateien-und-anhaenge.html#_23-5-verwaiste-dateien-finden-verschieben-und-loschen">Verwaiste Dateien finden, verschieben und löschen</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Trassen-Layer in QGIS lässt sich automatisch neu zeichnen, sobald jemand – in QGIS oder in der Weboberfläche – Trassen ändert: Die Datenbank sendet dafür die Benachrichtigung <code>qgis</code>. Aktivieren Sie in den Eigenschaften des Layers unter „Darstellung“ die Option „Layer bei Benachrichtigung aktualisieren“.</p></div><p>Bearbeiten zwei Personen dasselbe Objekt gleichzeitig, gewinnt die letzte Speicherung, ohne Warnung. Sprechen Sie größere Änderungen an einem Gebiet ab.</p><h2 id="_26-4-feldaufnahme-uber-geopackage-und-ruckfuhrung" tabindex="-1">26.4 Feldaufnahme über GeoPackage und Rückführung <a class="header-anchor" href="#_26-4-feldaufnahme-uber-geopackage-und-ruckfuhrung" aria-label="Permalink to &quot;26.4 Feldaufnahme über GeoPackage und Rückführung&quot;">​</a></h2><p>Für Aufnahmen ohne Verbindung zur Datenbank – im Feld, durch ein beauftragtes Büro – gibt es das GeoPackage-Schema: eine leere Datei mit dem Aufbau der Qonnectra-Tabellen, siehe Abschnitt <a href="./24-daten-import-und-export.html#_24-2-geopackage-schema-herunterladen">GeoPackage-Schema herunterladen</a>.</p><ol><li>Laden Sie ein Schema mit den benötigten Layern herunter und geben Sie die Datei an die aufnehmende Stelle. Welche Layer es enthält, legt die Konfiguration fest, siehe Abschnitt <a href="./22-projektbezogene-konfiguration.html#_22-4-geopackage-schema-konfigurieren">GeoPackage-Schema konfigurieren</a>.</li><li>Dort werden die Objekte in der Datei erfasst, mit derselben Spaltenstruktur wie in der Datenbank.</li><li>Öffnen Sie die zurückgegebene Datei in QGIS neben der Datenbankverbindung.</li><li>Prüfen Sie die Objekte: Projekt, Kennzeichen und Stammdaten-Nummern müssen zu Ihrer Installation passen.</li><li>Kopieren Sie die Objekte aus dem GeoPackage-Layer und fügen Sie sie im Bearbeitungsmodus in den Layer der Datenbank ein; speichern Sie.</li></ol><p>Für die Rückführung gibt es keinen Import in Qonnectra. Sie ist ein Kopieren in QGIS, und dabei gelten alle Regeln dieses Kapitels: Die Datenbank vergibt IDs und Längen und weist ungültige Geometrien ab.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Leeren Sie vor dem Einfügen die Spalten <code>uuid</code>, <code>id_trench</code> und <code>id_address</code>, falls die aufnehmende Stelle sie gefüllt hat. Eine UUID oder eine Trassen-ID, die es im Projekt schon gibt, lässt das Einfügen scheitern; die Datenbank vergibt beide selbst. Ebenso scheitert ein Netzknoten oder Gebiet, dessen Name im Projekt schon vergeben ist – benennen Sie solche Objekte vorher um.</p></div>',29)])])}const g=n(a,[["render",d]]);export{u as __pageData,g as default};
